contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single entry exercising fillOrder and checking minted ownerships and expiration invariant
    function run(C.Order memory order, bytes calldata signature, uint256[] memory floorAssetTokenIds) public payable {
        require(order.baseAsset != address(0), "baseAsset zero disabled");
        // ensure calldata lengths reasonable to avoid gas explosion in verifier
        require(order.duration < 10000 days, "duration too long");

        bool reverted;
        bytes32 orderHash = c.hashOrder(order);
        uint256 makerTokenId = uint256(orderHash);
        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 takerTokenId = uint256(opposite);

        // attempt to fill; capture revert
        try c.fillOrder(order, signature, floorAssetTokenIds) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After calling fillOrder (either reverted or succeeded) assert the general rule:
        // If it did not revert then ownerOf(makerTokenId) == order.maker and ownerOf(takerTokenId) == address(this) (msg.sender for calls is this contract)
        // and positionExpirations for the long side equals current block timestamp at fill time + order.duration.
        // Because we cannot read the exact block.timestamp at the time of the internal call, we instead assert that when not reverted:
        // - ownerOf for both tokens is not the zero address
        // - one owner equals order.maker and the other equals address(this)
        // - positionExpirations for the long position is > 0 (was set)

        if (!reverted) {
            address ownerMaker = c.ownerOf(makerTokenId);
            address ownerTaker = c.ownerOf(takerTokenId);
            uint256 posExpLong = c.positionExpirations(order.isLong ? makerTokenId : takerTokenId);

            // general rule formulated as a single assert combining the observations
            assert(
                ownerMaker != address(0) && ownerTaker != address(0) &&
                ((ownerMaker == order.maker && ownerTaker == address(this)) || (ownerTaker == order.maker && ownerMaker == address(this))) &&
                posExpLong > 0
            );
        } else {
            // If reverted, nothing further required: assert that the call indeed reverted implies no guarantees about owners.
            // But we must still reach exactly one assert statement in all executions — so here assert a relation involving reverted flag.
            assert(reverted == true);
        }
    }

    // allow receiving ETH if the test wants to forward it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising fillOrder and checking ownership + expiration invariant
    function run(C.Order memory order, bytes calldata signature, uint256[] memory floorAssetTokenIds) public payable {
        // basic preconditions to keep inputs reasonable for verifier
        require(order.duration < 10000 days, "duration too long");

        // compute ids observable externally
        bytes32 orderHash = c.hashOrder(order);
        uint256 makerTokenId = uint256(orderHash);
        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 takerTokenId = uint256(opposite);

        bool reverted;
        // perform the state-changing call as a top-level statement and capture revert
        try c.fillOrder(order, signature, floorAssetTokenIds) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after the call
        address ownerMaker;
        address ownerTaker;
        uint256 posExpLong;

        // Use external view calls (allowed) to observe contract state
        // If the tokens are not minted, ownerOf will revert; guard by try/catch via low-level staticcall
        // but solidity doesn't allow try on external view in this context, so use the public getters where possible.
        // ownerOf is a public function that reverts when not minted; to keep reads safe, we first check balanceOf for makerTokenId and takerTokenId via c._ownerOf is not accessible.
        // Instead, we will read ownerOf inside try/catch blocks.
        bool ownerReadsSucceeded = true;

        // read ownerMaker
        try c.ownerOf(makerTokenId) returns (address om) {
            ownerMaker = om;
        } catch {
            ownerReadsSucceeded = false;
            ownerMaker = address(0);
        }

        // read ownerTaker
        try c.ownerOf(takerTokenId) returns (address ot) {
            ownerTaker = ot;
        } catch {
            ownerReadsSucceeded = false;
            ownerTaker = address(0);
        }

        // positionExpirations has a public getter
        posExpLong = c.positionExpirations(order.isLong ? makerTokenId : takerTokenId);

        // Single assert expressing the general invariant:
        // If fillOrder reverted then reverted==true. If it did not revert then:
        //  - both owner reads must have succeeded and be nonzero
        //  - one of the owners equals order.maker and the other equals address(this)
        //  - the long-side position expiration is nonzero
        assert(
            (reverted == true) || (
                reverted == false &&
                ownerReadsSucceeded &&
                ownerMaker != address(0) &&
                ownerTaker != address(0) &&
                ((ownerMaker == order.maker && ownerTaker == address(this)) || (ownerTaker == order.maker && ownerMaker == address(this))) &&
                posExpLong != 0
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test: ensure cancel by maker marks the order cancelled, and non-maker calls revert
    function run(C.Order memory order) public payable {
        // keep duration/expiration reasonable to avoid weird reverts elsewhere
        require(order.duration < 10000 days, "duration too long");

        bytes32 orderHash = c.hashOrder(order);

        bool revertedWhenNonMaker;
        // try calling cancel as this contract (which is NOT the maker unless caller provided that address)
        try c.cancel(order) {
            revertedWhenNonMaker = false;
        } catch {
            revertedWhenNonMaker = true;
        }

        // Now emulate the maker calling cancel by calling through c as if this contract were the maker is impossible;
        // but we can only call c.cancel from this contract. To satisfy the property we require the maker equals address(this)
        // in precondition so that the subsequent call is a valid maker call and will succeed.
        // Therefore require that order.maker == address(this) so the previous attempt represents the maker call.
        // However the checker runs run(...) once; to make a clear property we demand maker==address(this) upfront.
        // (Enforce via require so the single assert is general over all inputs meeting precondition.)
        require(order.maker == address(this), "precondition: maker must be this contract");

        // Now call cancel as the maker (this contract) — top-level state-changing call
        c.cancel(order);

        // Observe cancelledOrders via public getter
        bool cancelled = c.cancelledOrders(orderHash);

        // If the initial attempt by non-maker did not revert then that initial attempt must have been by the maker (contradiction to precondition),
        // but because we required maker==address(this), the first try represented a maker call and should not have reverted; in that case cancelled should be true.
        // General rule: when the maker calls cancel(order), cancelledOrders[hashOrder(order)] == true.
        assert(cancelled == true);
    }

    receive() external payable {}
}

