contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test properties of fillOrder for the branch: !isLong && !isCall
    // Parameters provide an order with minimal valid fields. We pass empty arrays for assets.
    function run(
        address maker,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(maker != address(0));
        require(baseAsset != address(0));
        // build order struct in memory via C.Order type
        C.Order memory order = C.Order({
            maker: maker,
            isCall: false,
            isLong: false,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        // signature must be valid otherwise fillOrder reverts; we can't produce a valid signature here
        // so we expect fillOrder to revert for arbitrary signature. We assert that if it does NOT revert,
        // then observable invariants hold: positions minted and owner checks and expiration set.
        bytes memory fakeSig = hex"00"; // likely invalid

        bool didRevert;
        uint256 positionId;
        try c.fillOrder(order, fakeSig, new uint256[](0)) returns (uint256 pid) {
            didRevert = false;
            positionId = pid;
        } catch {
            didRevert = true;
        }

        // Compute order hashes via public view functions
        bytes32 orderHash = c.hashOrder(order);
        bytes32 opposite = c.hashOppositeOrder(order);
        uint256 shortPositionId = uint256(orderHash);
        uint256 longPositionId = uint256(opposite);

        // If the call succeeded (didRevert == false) then:
        // - ownerOf(shortPositionId) == maker (the contract mints to maker)
        // - ownerOf(longPositionId) == address(this) ? NO: per fillOrder long minted to msg.sender (filler), which is this contract when calling through InvMutTest
        // In this test context, msg.sender for c calls is address(this) (InvMutTest). So long position owner should be address(this).
        // - positionExpirations[shortPositionId] should be set to block.timestamp + duration
        // We fetch these via public getters. ownerOf may revert if not minted; so only check when not reverted.

        if (!didRevert) {
            address ownerShort = c.ownerOf(shortPositionId);
            address ownerLong = c.ownerOf(longPositionId);
            uint256 expShort = c.positionExpirations(shortPositionId);
            // General rule asserted below
            assert(ownerShort == maker && ownerLong == address(this) && expShort == block.timestamp + duration);
        } else {
            // If it reverted, assert nothing about state except that we observed revert (we must still satisfy single assert):
            assert(didRevert == true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test fillOrder behavior for short non-call orders (!isLong && !isCall).
    function run(
        address maker,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        bytes calldata signature
    ) public payable {
        // basic preconditions to avoid meaningless inputs
        require(maker != address(0));
        require(baseAsset != address(0));

        C.Order memory order = C.Order({
            maker: maker,
            isCall: false,
            isLong: false,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        // Perform the state-changing call as a top-level statement and catch revert via try/catch
        bool didRevert;
        uint256 returnedPositionId;
        try c.fillOrder(order, signature, new uint256[](0)) returns (uint256 pid) {
            didRevert = false;
            returnedPositionId = pid;
        } catch {
            didRevert = true;
            returnedPositionId = 0;
        }

        // Observe public state after the call (or revert)
        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 shortId = uint256(orderHash);
        uint256 longId = uint256(oppositeHash);

        // Read observable getters (ownerOf may revert if not minted; use low-level try to detect that)
        bool shortOwnerReadable;
        address shortOwner;
        try c.ownerOf(shortId) returns (address o) {
            shortOwnerReadable = true;
            shortOwner = o;
        } catch {
            shortOwnerReadable = false;
            shortOwner = address(0);
        }

        bool longOwnerReadable;
        address longOwner;
        try c.ownerOf(longId) returns (address o2) {
            longOwnerReadable = true;
            longOwner = o2;
        } catch {
            longOwnerReadable = false;
            longOwner = address(0);
        }

        uint256 shortExpiration = c.positionExpirations(shortId);

        // Exactly one assert: if the call did not revert then the short owner must equal maker,
        // the long owner must equal this contract (the filler), and the short expiration must be block.timestamp + duration.
        // If the call reverted then didRevert must be true (we assert that either the call reverted or the postconditions hold).
        assert(didRevert || (shortOwnerReadable && longOwnerReadable && shortOwner == maker && longOwner == address(this) && shortExpiration == block.timestamp + duration));
    }

    receive() external payable {}
}
